**Windows x64 — 先枚举模块拿基址（C++，可直接编译）**

```cpp
// build: cl /std:c++17 /EHsc modscan.cpp
#include <windows.h>
#include <tlhelp32.h>
#include <psapi.h>
#include <cstdio>
#include <string>

#pragma comment(lib, "psapi.lib")

static DWORD FindPid(const wchar_t* name) {
    HANDLE snap = CreateToolhelp32Snapshot(TH32CS_SNAPPROCESS, 0);
    if (snap == INVALID_HANDLE_VALUE) return 0;
    PROCESSENTRY32W pe{ sizeof(pe) };
    DWORD pid = 0;
    if (Process32FirstW(snap, &pe)) {
        do {
            if (_wcsicmp(pe.szExeFile, name) == 0) { pid = pe.th32ProcessID; break; }
        } while (Process32NextW(snap, &pe));
    }
    CloseHandle(snap);
    return pid;
}

int wmain(int argc, wchar_t** argv) {
    const wchar_t* target = (argc > 1) ? argv[1] : L"[进程名]";
    DWORD pid = FindPid(target);
    if (!pid) { wprintf(L"[-] process %s not found\n", target); return 1; }

    HANDLE h = OpenProcess(PROCESS_QUERY_INFORMATION | PROCESS_VM_READ, FALSE, pid);
    if (!h) { wprintf(L"[-] OpenProcess failed: %lu\n", GetLastError()); return 2; }

    HMODULE mods[1024]; DWORD need = 0;
    if (!EnumProcessModulesEx(h, mods, sizeof(mods), &need, LIST_MODULES_ALL)) {
        wprintf(L"[-] EnumProcessModulesEx failed: %lu\n", GetLastError());
        CloseHandle(h); return 3;
    }
    DWORD cnt = need / sizeof(HMODULE);
    wprintf(L"[+] pid=%lu modules=%lu\n", pid, cnt);
    for (DWORD i = 0; i < cnt; ++i) {
        wchar_t path[MAX_PATH]{}; wchar_t base[MAX_PATH]{};
        GetModuleBaseNameW(h, mods[i], base, MAX_PATH);
        GetModuleFileNameExW(h, mods[i], path, MAX_PATH);
        MODULEINFO mi{};
        GetModuleInformation(h, mods[i], &mi, sizeof(mi));
        wprintf(L"  %-32s base=%p size=0x%08lX  %s\n",
                base, mi.lpBaseOfDll, mi.SizeOfImage, path);
    }
    CloseHandle(h);
    return 0;
}
```

