**第一步：确认进程与模块基址（C++）**

```cpp
#include <windows.h>
#include <tlhelp32.h>
#include <vector>
#include <string>

DWORD GetPid(const wchar_t* name) {
    HANDLE snap = CreateToolhelp32Snapshot(TH32CS_SNAPPROCESS, 0);
    PROCESSENTRY32W pe{ sizeof(pe) };
    for (BOOL ok = Process32FirstW(snap, &pe); ok; ok = Process32NextW(snap, &pe))
        if (!_wcsicmp(pe.szExeFile, name)) { CloseHandle(snap); return pe.th32ProcessID; }
    CloseHandle(snap);
    return 0;
}

uintptr_t GetModuleBase(DWORD pid, const wchar_t* mod) {
    HANDLE snap = CreateToolhelp32Snapshot(TH32CS_SNAPMODULE | TH32CS_SNAPMODULE32, pid);
    MODULEENTRY32W me{ sizeof(me) };
    for (BOOL ok = Module32FirstW(snap, &me); ok; ok = Module32NextW(snap, &me))
        if (!_wcsicmp(me.szModule, mod)) { CloseHandle(snap); return (uintptr_t)me.modBaseAddr; }
    CloseHandle(snap);
    return 0;
}

int wmain() {
    const wchar_t* PROC = L"[进程名].exe";   // ← 替换
    const wchar_t* MOD  = L"[模块名].exe";    // ← 替换（Unreal 常为游戏主 exe / GameAssembly.dll）
    DWORD pid = GetPid(PROC);
    if (!pid) { printf("pid not found\n"); return 1; }
    HANDLE h = OpenProcess(PROCESS_VM_READ | PROCESS_VM_WRITE | PROCESS_VM_OPERATION | PROCESS_QUERY_INFORMATION, FALSE, pid);
    if (!h) { printf("OpenProcess failed: %lu\n", GetLastError()); return 1; }
    printf("pid=%lu base=0x%llX\n", pid, (unsigned long long)GetModuleBase(pid, MOD));
    return 0;
}
