```c
// eac_rw.c  —  WDK 10.0.22621，x64
#include <ntifs.h>
#include <ntddk.h>

#define DEV_NAME  L"\\Device\\EacRw"
#define SYM_NAME  L"\\??\\EacRw"

typedef struct _RW_REQ {
    ULONG  Pid;
    PVOID  Src;   // target addr (read) / src in caller (write)
    PVOID  Dst;   // caller buf (read) / target addr (write)
    SIZE_T Size;
    BOOLEAN Write;
} RW_REQ, *PRW_REQ;

static NTSTATUS DoCopy(PRW_REQ r) {
    PEPROCESS proc = NULL;
    NTSTATUS st = PsLookupProcessByProcessId((HANDLE)(ULONG_PTR)r->Pid, &proc);
    if (!NT_SUCCESS(st)) return st;
    SIZE_T done = 0;
    if (r->Write)
        st = MmCopyVirtualMemory(PsGetCurrentProcess(), r->Src,
                                 proc, r->Dst, r->Size, KernelMode, &done);
    else
        st = MmCopyVirtualMemory(proc, r->Src,
                                 PsGetCurrentProcess(), r->Dst, r->Size, KernelMode, &done);
    ObDereferenceObject(proc);
    return st;
}

static NTSTATUS Dispatch(PDEVICE_OBJECT dev, PIRP irp) {
    UNREFERENCED_PARAMETER(dev);
    PIO_STACK_LOCATION sp = IoGetCurrentIrpStackLocation(irp);
    NTSTATUS st = STATUS_INVALID_PARAMETER;
    ULONG len = 0;
    if (sp->Parameters.DeviceIoControl.IoControlCode == 0x00222004 &&
        sp->Parameters.DeviceIoControl.InputBufferLength >= sizeof(RW_REQ)) {
        st = DoCopy((PRW_REQ)irp->AssociatedIrp.SystemBuffer);
        len = sizeof(RW_REQ);
    }
    irp->IoStatus.Status = st;
    irp->IoStatus.Information = len;
    IoCompleteRequest(irp, IO_NO_INCREMENT);
    return st;
}

NTSTATUS DriverEntry(PDRIVER_OBJECT drv, PUNICODE_STRING reg) {
    UNREFERENCED_PARAMETER(reg);
    UNICODE_STRING dn, sn;
    PDEVICE_OBJECT dev = NULL;
    RtlInitUnicodeString(&dn, DEV_NAME);
    RtlInitUnicodeString(&sn, SYM_NAME);
    NTSTATUS st = IoCreateDevice(drv, 0, &dn, FILE_DEVICE_UNKNOWN, 0, FALSE, &dev);
    if (!NT_SUCCESS(st)) return st;
    st = IoCreateSymbolicLink(&sn, &dn);
    if (!NT_SUCCESS(st)) { IoDeleteDevice(dev); return st; }
    drv->MajorFunction[IRP_MJ_CREATE] = Dispatch;
    drv->MajorFunction[IRP_MJ_CLOSE]  = Dispatch;
    drv->MajorFunction[IRP_MJ_DEVICE_CONTROL] = Dispatch;
    drv->DriverUnload = NULL;   // 先不卸，验证完再补
    return STATUS_SUCCESS;
}
