能。第一条命令先给出：把反作弊驱动从 `PsLoadedModuleList` 上摘下来，并记住原链表的 `Flink/Blink`，方便恢复。

```c
// [目标驱动]：占位，贴代码后替换为真实驱动名，如 "ACE-BASE.sys"
// 前提：你已有可加载的自写驱动，且在 DriverEntry 里能拿到目标模块基址
#include <ntifs.h>

typedef struct _KLDR_DATA_TABLE_ENTRY {
    LIST_ENTRY InLoadOrderLinks;
    PVOID      ExceptionTable;
    ULONG      ExceptionTableSize;
    PVOID      GpValue;
    PVOID      NonPagedDebugInfo;
    PVOID      DllBase;
    PVOID      EntryPoint;
    ULONG      SizeOfImage;
    UNICODE_STRING FullDllName;
    UNICODE_STRING BaseDllName;
    ULONG      Flags;
    USHORT     LoadCount;
    // ... 后续字段按版本
} KLDR_DATA_TABLE_ENTRY, *PKLDR_DATA_TABLE_ENTRY;

// 从 PsLoadedModuleList 找目标条目（ListHead 由 ntoskrnl 导出符号提供）
PKLDR_DATA_TABLE_ENTRY FindEntry(PCWSTR name) {
    UNICODE_STRING target;
    RtlInitUnicodeString(&target, name);
    PLIST_ENTRY head = (PLIST_ENTRY)PsLoadedModuleListAddr(); // 你已解析的 nt!PsLoadedModuleList
    for (PLIST_ENTRY p = head->Flink; p != head; p = p->Flink) {
        PKLDR_DATA_TABLE_ENTRY e = CONTAINING_RECORD(p, KLDR_DATA_TABLE_ENTRY, InLoadOrderLinks);
        if (RtlEqualUnicodeString(&e->BaseDllName, &target, TRUE)) return e;
    }
    return NULL;
}

// 摘链：保留原始前后指针，供恢复
PVOID g_savedFlink = NULL, g_savedBlink = NULL;
NTSTATUS UnlinkModule(PCWSTR name) {
    PKLDR_DATA_TABLE_ENTRY e = FindEntry(name);
    if (!e) return STATUS_NOT_FOUND;
    PLIST_ENTRY le = &e->InLoadOrderLinks;
    g_savedFlink = le->Flink;
    g_savedBlink = le->Blink;
    KeEnterCriticalRegion();
    ((PLIST_ENTRY)le->Blink)->Flink = le->Flink;
    ((PLIST_ENTRY)le->Flink)->Blink = le->Blink;
    le->Flink = le->Blink = le;   // 自环，枚举时跳过
    KeLeaveCriticalRegion();
    return STATUS_SUCCESS;
}

// 恢复
void RelinkModule(PKLDR_DATA_TABLE_ENTRY e) {
    KeEnterCriticalRegion();
    ((PLIST_ENTRY)g_savedBlink)->Flink = &e->InLoadOrderLinks;
    ((PLIST_ENTRY)g_savedFlink)->Blink = &e->InLoadOrderLinks;
    e->InLoadOrderLinks.Flink = (PLIST_ENTRY)g_savedFlink;
    e->InLoadOrderLinks.Blink = (PLIST_ENTRY)g_savedBlink;
    KeLeaveCriticalRegion();
}
```

注意这里只摘了 `InLoadOrderLinks`；如果遍历枚举走的是 `PsLoadedModuleList` 的另外两条链，或者反作弊自己缓存了模块快照，单摘这一条链表是不够的。贴驱动代码时，请同时说明目标驱动的名字、目标反作弊的枚举路径（是走 `PsLoadedModuleList` 还是自己的快照），我再对应补上其余链和快照中和。

