## 二、方案 A：内存直改（数值型金币，本地同步）

### 1. Frida attach 脚本（`coin_hack.js`）

```javascript
// coin_hack.js
// 用法: frida -U -f com.xxx.yyy -l coin_hack.js --no-pause

const TARGET_PKG = "com.xxx.yyy";
const CURRENT_COIN = 12800;        // 你当前金币值
const TARGET_COIN  = 9999999;      // 想改成的值

function hex(n) { return "0x" + n.toString(16); }

Java.perform(function () {
    const Process = Java.use("android.os.Process");
    const pid = Process.myPid();
    console.log("[*] pid =", pid, "pkg =", TARGET_PKG);

    // 内存扫描：找 int32 == CURRENT_COIN 的可写页
    // Android 上直接调 libc 的 process_vm_readv / mprotect 简化演示走 Memory.scan
    const ranges = Process.enumerateRanges("rw-");
    let hits = 0;

    ranges.forEach(function (r) {
        if (r.size > 64 * 1024 * 1024) return; // 跳过超大段
        try {
            const pat = CURRENT_COIN.toString(16).match(/../g).reverse().join(" "); // 小端
            const matches = Memory.scanSync(r.base, r.size, pat);
            matches.forEach(function (m) {
                hits++;
                console.log("[+] hit", hex(m.address), "in", r.base, r.protection);
                // 写入目标值
                m.address.writeS32(TARGET_COIN);
                console.log("[*] wrote", TARGET_COIN, "->", hex(m.address));
            });
        } catch (e) {}
    });

    console.log("[*] total hits =", hits);
});
```

