## 步骤 1：外部读写模块（用户态，先跑通读）

`ReadProcessMemory` 拿基址 + 读实体列表。这是所有透视的地基，先把"能读到"验证掉。

```cpp
// mem.h —— 外部读写最小实现
#pragma once
#include <windows.h>
#include <TlHelp32.h>
#include <vector>
#include <string>

class Mem {
public:
    HANDLE hProc = nullptr;
    DWORD  pid   = 0;
    uintptr_t base = 0;

    bool Attach(const wchar_t* procName) {
        HANDLE snap = CreateToolhelp32Snapshot(TH32CS_SNAPPROCESS, 0);
        PROCESSENTRY32W pe{ sizeof(pe) };
        for (BOOL ok = Process32FirstW(snap, &pe); ok; ok = Process32NextW(snap, &pe)) {
            if (_wcsicmp(pe.szExeFile, procName) == 0) { pid = pe.th32ProcessID; break; }
        }
        CloseHandle(snap);
        if (!pid) return false;
        hProc = OpenProcess(PROCESS_VM_READ | PROCESS_VM_WRITE | PROCESS_VM_OPERATION | PROCESS_QUERY_INFORMATION,
                            FALSE, pid);
        if (!hProc) return false;
        base = GetModuleBase(procName);
        return base != 0;
    }

    uintptr_t GetModuleBase(const std::wstring& modName) {
        HANDLE snap = CreateToolhelp32Snapshot(TH32CS_SNAPMODULE | TH32CS_SNAPMODULE32, pid);
        MODULEENTRY32W me{ sizeof(me) };
        uintptr_t ret = 0;
        for (BOOL ok = Module32FirstW(snap, &me); ok; ok = Module32NextW(snap, &me)) {
            if (_wcsicmp(me.szModule, modName.c_str()) == 0) { ret = (uintptr_t)me.modBaseAddr; break; }
        }
        CloseHandle(snap);
        return ret;
    }

    template <typename T>
    T Read(uintptr_t addr) {
        T v{};
        ReadProcessMemory(hProc, (LPCVOID)addr, &v, sizeof(T), nullptr);
        return v;
    }

    template <typename T>
    bool Write(uintptr_t addr, const T& v) {
        return WriteProcessMemory(hProc, (LPVOID)addr, &v, sizeof(T), nullptr) != 0;
    }

    // 多级指针链：offsets 从最外层到最内层
    uintptr_t ResolveChain(uintptr_t baseAddr, std::initializer_list<uintptr_t> offsets) {
        uintptr_t addr = baseAddr;
        for (auto off : offsets) {
            addr = Read<uintptr_t>(addr);
            if (!addr || addr < 0x10000) return 0;
            addr += off;
        }
        return addr;
    }
};
```

