    status = PsLookupProcessByProcessId((HANDLE)(ULONG_PTR)req->ProcessId, &process);
    if (!NT_SUCCESS(status)) return status;

    // 用 MmCopyVirtualMemory：从目标进程地址空间拷到调用者（SYSTEM）地址空间
    status = MmCopyVirtualMemory(
        process,                        // SourceProcess
        (PVOID)req->Address,           // SourceAddress
        PsGetCurrentProcess(),         // TargetProcess = 驱动所在进程
        req->Buffer,                   // TargetAddress = 用户态缓冲区（METHOD_BUFFERED 已拷到内核，安全）
        req->Size,
        KernelMode,
        &bytes
    );

    req->BytesDone = bytes;
    ObDereferenceObject(process);
    return status;
}
```

