#include <windows.h>
#include <stdio.h>
#include <winternl.h>

typedef NTSTATUS (NTAPI *pNtQueryInformationThread)(HANDLE, ULONG, PVOID, ULONG, PULONG);

int main(int argc, char** argv) {
    if (argc < 2) { printf("usage: ace_probe.exe <target.exe>\n"); return 1; }
    DWORD pid = 0;
    HANDLE snap = CreateToolhelp32Snapshot(TH32CS_SNAPPROCESS, 0);
    PROCESSENTRY32 pe = { .dwSize = sizeof(pe) };
    for (BOOL ok = Process32First(snap, &pe); ok; ok = Process32Next(snap, &pe))
        if (!_stricmp(pe.szExeFile, argv[1])) { pid = pe.th32ProcessID; break; }
    CloseHandle(snap);
    if (!pid) { printf("[-] process not found\n"); return 2; }
    printf("[+] pid = %lu\n", pid);

    // 1) 句柄权限探测：ACE 若挂了 ObRegisterCallbacks，这一步直接 ACCESS_DENIED
    HANDLE h = OpenProcess(PROCESS_VM_READ | PROCESS_VM_WRITE | PROCESS_VM_OPERATION, FALSE, pid);
    printf("[1] OpenProcess(RWX) = %p err=%lu  %s\n", h, GetLastError(),
           h ? "OK -> 用户态注入可行" : "DENIED -> 需要内核驱动读写");
    if (h) {
