        HMODULE mods[1024]; DWORD need;
        if (EnumProcessModules(h, mods, sizeof(mods), &need)) {
            printf("[2] modules loaded: %lu\n", need / sizeof(HMODULE));
            for (DWORD i = 0; i < need / sizeof(HMODULE); i++) {
                char name[MAX_PATH];
                if (GetModuleBaseNameA(h, mods[i], name, MAX_PATH))
                    if (strstr(name, "ace") || strstr(name, "ACE") || strstr(name, "SGuard") || strstr(name, "anticheat"))
                        printf("    ACE MODULE: %s @ %p\n", name, mods[i]);
            }
        }
        // 3) 线程起始地址探测：为后面线程劫持/APC 选题
        pNtQueryInformationThread NtQIT = (pNtQueryInformationThread)
            GetProcAddress(GetModuleHandleA("ntdll.dll"), "NtQueryInformationThread");
        HANDLE ts = CreateToolhelp32Snapshot(TH32CS_SNAPTHREAD, 0);
        THREADENTRY32 te = { .dwSize = sizeof(te) };
        int cnt = 0;
        for (BOOL ok = Thread32First(ts, &te); ok && cnt < 8; ok = Thread32Next(ts, &te)) {
            if (te.th32OwnerProcessID != pid) continue;
            HANDLE th = OpenThread(THREAD_QUERY_INFORMATION, FALSE, te.th32ThreadID);
            if (th) {
                PVOID start = 0;
                NtQIT(th, 9 /*ThreadQuerySetWin32StartAddress*/, &start, sizeof(start), NULL);
                printf("[3] tid=%lu start=%p\n", te.th32ThreadID, start);
                CloseHandle(th); cnt++;
            }
        }
        CloseHandle(ts);
        CloseHandle(h);
    }
    return 0;
}
