// 编译: cl /EHsc kmbox_send.cpp  或  g++ -O2 kmbox_send.cpp -o kmbox_send
#include <windows.h>
#include <cstdint>
#include <cstdio>

static HANDLE g_h = INVALID_HANDLE_VALUE;

bool kmbox_open(const char* port /* "[COM端口]" 例如 "\\\\.\\COM5" */) {
    char full[64];
    snprintf(full, sizeof(full), "\\\\.\\%s", port);
    g_h = CreateFileA(full, GENERIC_READ | GENERIC_WRITE, 0, nullptr,
                      OPEN_EXISTING, 0, nullptr);
    if (g_h == INVALID_HANDLE_VALUE) { printf("open fail %lu\n", GetLastError()); return false; }
    DCB dcb{}; dcb.DCBlength = sizeof(dcb);
    GetCommState(g_h, &dcb);
    dcb.BaudRate = 115200;   // kmbox 常见 115200 / 921600，按固件改
    dcb.ByteSize = 8; dcb.Parity = NOPARITY; dcb.StopBits = ONESTOPBIT;
    dcb.fBinary = TRUE; dcb.fDtrControl = DTR_CONTROL_ENABLE; dcb.fRtsControl = RTS_CONTROL_ENABLE;
    SetCommState(g_h, &dcb);
    COMMTIMEOUTS to{}; to.WriteTotalTimeoutConstant = 50; to.ReadIntervalTimeout = 20;
    SetCommTimeouts(g_h, &to);
    PurgeComm(g_h, PURGE_RXCLEAR | PURGE_TXCLEAR);
    return true;
}

void kmbox_close() { if (g_h != INVALID_HANDLE_VALUE) CloseHandle(g_h); }

// P 系列 8 字节帧: FC FC CMD dx(int16) dy(int16) btn
bool kmbox_move(int16_t dx, int16_t dy) {
    uint8_t f[8] = {0xFC, 0xFC, 0x01,
                    (uint8_t)(dx & 0xFF), (uint8_t)((dx >> 8) & 0xFF),
                    (uint8_t)(dy & 0xFF), (uint8_t)((dy >> 8) & 0xFF),
                    0x00};
    DWORD written = 0;
    return WriteFile(g_h, f, 8, &written, nullptr) && written == 8;
}

bool kmbox_click(uint8_t btn /* 0x01 左 0x02 右 0x04 中 */) {
    uint8_t f[3] = {0xFC, 0xFC, (uint8_t)(0x02 | (btn << 4))};
    DWORD w = 0;
    return WriteFile(g_h, f, 3, &w, nullptr);
}

