#include <windows.h>
#include <tlhelp32.h>
#include <stdio.h>

static DWORD GetPID(const wchar_t* name) {
    HANDLE snap = CreateToolhelp32Snapshot(TH32CS_SNAPPROCESS, 0);
    PROCESSENTRY32W pe{ sizeof(pe) };
    DWORD pid = 0;
    if (Process32FirstW(snap, &pe)) {
        do { if (!_wcsicmp(pe.szExeFile, name)) { pid = pe.th32ProcessID; break; } }
        while (Process32NextW(snap, &pe));
    }
    CloseHandle(snap);
    return pid;
}

static uintptr_t GetModBase(DWORD pid, const wchar_t* mod) {
    HANDLE snap = CreateToolhelp32Snapshot(TH32CS_SNAPMODULE | TH32CS_SNAPMODULE32, pid);
    MODULEENTRY32W me{ sizeof(me) };
    uintptr_t base = 0;
    if (Module32FirstW(snap, &me)) {
        do { if (!_wcsicmp(me.szModule, mod)) { base = (uintptr_t)me.modBaseAddr; break; } }
        while (Module32NextW(snap, &me));
    }
    CloseHandle(snap);
    return base;
}

int wmain() {
    DWORD pid = GetPID(L"[进程名]");
    if (!pid) { printf("pid not found\n"); return 1; }

    HANDLE h = OpenProcess(PROCESS_VM_READ | PROCESS_VM_WRITE | PROCESS_VM_OPERATION, FALSE, pid);
    if (!h) { printf("OpenProcess failed: %lu\n", GetLastError()); return 1; }

    uintptr_t base = GetModBase(pid, L"[模块名]");
    printf("pid=%lu base=%p\n", pid, (void*)base);

    // 改内存前先 dump 原值，留回滚
    uintptr_t addr = base + [偏移];
    int oldVal = 0, newVal = [新值];
    SIZE_T rd = 0;
    if (!ReadProcessMemory(h, (void*)addr, &oldVal, sizeof(oldVal), &rd)) {
        printf("RPM failed: %lu\n", GetLastError());
        CloseHandle(h); return 1;
    }
    printf("old=0x%X\n", oldVal);
    WriteProcessMemory(h, (void*)addr, &newVal, sizeof(newVal), NULL);

    // 回滚: WriteProcessMemory(h, (void*)addr, &oldVal, sizeof(oldVal), NULL);
    CloseHandle(h);
    return 0;
}
