先给第一条可执行内容：按占位符直接开工，Windows x64 用户态读写骨架如下，编译即可跑，拿去替换 `[进程名]` / `[模块名]` 就能用。

```cpp
// get_module_base.cpp —— cl /std:c++17 /EHsc get_module_base.cpp
#include <windows.h>
#include <tlhelp32.h>
#include <psapi.h>
#include <cstdio>
#include <string>
#include <vector>

struct ModInfo { std::wstring name; uintptr_t base; size_t size; };

std::vector<ModInfo> EnumModules(DWORD pid) {
    std::vector<ModInfo> out;
    HANDLE hSnap = CreateToolhelp32Snapshot(TH32CS_SNAPMODULE | TH32CS_SNAPMODULE32, pid);
    if (hSnap == INVALID_HANDLE_VALUE) return out;
    MODULEENTRY32W me{ sizeof(me) };
    if (Module32FirstW(hSnap, &me)) {
        do {
            out.push_back({ me.szModule, (uintptr_t)me.modBaseAddr, me.modBaseSize });
        } while (Module32NextW(hSnap, &me));
    }
    CloseHandle(hSnap);
    return out;
}

int wmain(int argc, wchar_t** argv) {
    const wchar_t* procName = (argc > 1) ? argv[1] : L"[进程名].exe";
    DWORD pid = 0;
    HANDLE hSnap = CreateToolhelp32Snapshot(TH32CS_SNAPPROCESS, 0);
    PROCESSENTRY32W pe{ sizeof(pe) };
    if (Process32FirstW(hSnap, &pe)) {
        do {
            if (_wcsicmp(pe.szExeFile, procName) == 0) { pid = pe.th32ProcessID; break; }
        } while (Process32NextW(hSnap, &pe));
    }
    CloseHandle(hSnap);
    if (!pid) { wprintf(L"process not found\n"); return 1; }

    wprintf(L"pid = %lu\n", pid);
    for (auto& m : EnumModules(pid))
        wprintf(L"%-40s base=0x%016llX size=0x%08zX\n",
                m.name.c_str(), (unsigned long long)m.base, m.size);
    return 0;
}
```

拿到 `[模块名]` 的 `base` 后，读写层用这个（`NtReadVirtualMemory` 走 syscall 层更稳，对用户态钩子免疫）：

```cpp
// memrw.cpp —— 读写原语，先 dump 原值再改，保证可回滚
#pragma comment(lib, "ntdll.lib")
#include <windows.h>
#include <winternl.h>

typedef NTSTATUS(NTAPI* pNtRVM)(HANDLE, PVOID, PVOID, SIZE_T, PSIZE_T);
typedef NTSTATUS(NTAPI* pNtWVM)(HANDLE, PVOID, PVOID, SIZE_T, PSIZE_T);

struct Rw {
    HANDLE h; pNtRVM rd; pNtWVM wr;

    bool open(DWORD pid) {
        h = OpenProcess(PROCESS_VM_READ | PROCESS_VM_WRITE | PROCESS_VM_OPERATION, FALSE, pid);
        rd = (pNtRVM)GetProcAddress(GetModuleHandleW(L"ntdll.dll"), "NtReadVirtualMemory");
        wr = (pNtWVM)GetProcAddress(GetModuleHandleW(L"ntdll.dll"), "NtWriteVirtualMemory");
        return h && rd && wr;
    }

    template <class T> bool read(uintptr_t addr, T& out) {
        SIZE_T n = 0;
        return addr && rd(h, (PVOID)addr, &out, sizeof(T), &n) == 0 && n == sizeof(T);
    }

    // 回滚用：改之前先把原值打印出来存档
    template <class T> bool write(uintptr_t addr, const T& val) {
        T old{};
        if (read(addr, old))
            printf("[dump] 0x%llX old=0x%llX -> new=0x%llX\n",
                   (unsigned long long)addr, (unsigned long long)old, (unsigned long long)val);
        SIZE_T n = 0;
        return wr(h, (PVOID)addr, (PVOID)&val, sizeof(T), &n) == 0 && n == sizeof(T);
    }

    // 多级指针链：offsets 从顶层往下，[模块基址] + o[0] 解引用 + o[1] ...
    uintptr_t resolve(uintptr_t base, const std::vector<uintptr_t>& o) {
        uintptr_t p = base;
        for (size_t i = 0; i + 1 < o.size(); ++i) {
            uintptr_t next = 0;
            if (!read(p + o[i], next)) return 0;
            p = next;
        }
        return p + o.back();
    }
};
```

