```cpp
// rw.cpp — OpenProcess + 模块基址 + 多级指针链
// 编译：cl /std:c++17 /EHsc rw.cpp
#include <windows.h>
#include <tlhelp32.h>
#include <vector>
#include <cstdio>

DWORD GetPid(const wchar_t* name) {
    HANDLE snap = CreateToolhelp32Snapshot(TH32CS_SNAPPROCESS, 0);
    PROCESSENTRY32W pe{ sizeof(pe) };
    for (BOOL ok = Process32FirstW(snap, &pe); ok; ok = Process32NextW(snap, &pe))
        if (!_wcsicmp(pe.szExeFile, name)) { CloseHandle(snap); return pe.th32ProcessID; }
    CloseHandle(snap);
    return 0;
}

// 模块基址：走 PEB 或 Toolhelp 二选一
uint64_t GetModuleBase(DWORD pid, const wchar_t* mod) {
    HANDLE snap = CreateToolhelp32Snapshot(TH32CS_SNAPMODULE | TH32CS_SNAPMODULE32, pid);
    MODULEENTRY32W me{ sizeof(me) };
    for (BOOL ok = Module32FirstW(snap, &me); ok; ok = Module32NextW(snap, &me))
        if (!_wcsicmp(me.szModule, mod)) { CloseHandle(snap); return (uint64_t)me.modBaseAddr; }
    CloseHandle(snap);
    return 0;
}

template<typename T>
bool RPM(HANDLE h, uint64_t addr, T& out) {
    SIZE_T n = 0;
    return ReadProcessMemory(h, (LPCVOID)addr, &out, sizeof(T), &n) && n == sizeof(T);
}

// 多级指针链：offsets 为从基址到目标的偏移数组
// 例：base + [offsets[0]] -> +[offsets[1]] -> ... -> +offsets.back()
uint64_t FollowChain(HANDLE h, uint64_t base, const std::vector<uint64_t>& offsets) {
    uint64_t addr = base;
    for (size_t i = 0; i + 1 < offsets.size(); ++i) {
        uint64_t next = 0;
        if (!RPM(h, addr + offsets[i], next)) return 0;
        addr = next;
    }
    return addr + offsets.back();
}

int wmain() {
    DWORD pid = GetPid(L"[进程名]");
    if (!pid) { printf("进程未找到\n"); return 1; }
