// mem_probe.cpp —— 编译：cl /EHsc mem_probe.cpp
// 作用：打开 game.exe，枚举主模块基址，dump 前 0x1000 字节做基线备份
#include <windows.h>
#include <tlhelp32.h>
#include <cstdio>

DWORD FindPid(const wchar_t* name) {
    HANDLE snap = CreateToolhelp32Snapshot(TH32CS_SNAPPROCESS, 0);
    PROCESSENTRY32W pe{ sizeof(pe) };
    for (BOOL ok = Process32FirstW(snap, &pe); ok; ok = Process32NextW(snap, &pe))
        if (!_wcsicmp(pe.szExeFile, name)) { CloseHandle(snap); return pe.th32ProcessID; }
    CloseHandle(snap); return 0;
}

ULONG_PTR FindModBase(DWORD pid, const wchar_t* mod) {
    HANDLE snap = CreateToolhelp32Snapshot(TH32CS_SNAPMODULE | TH32CS_SNAPMODULE32, pid);
    MODULEENTRY32W me{ sizeof(me) };
    for (BOOL ok = Module32FirstW(snap, &me); ok; ok = Module32NextW(snap, &me))
        if (!_wcsicmp(me.szModule, mod)) { ULONG_PTR b = (ULONG_PTR)me.modBaseAddr; CloseHandle(snap); return b; }
    CloseHandle(snap); return 0;
}

int wmain(int argc, wchar_t** argv) {
    const wchar_t* exe = argc > 1 ? argv[1] : L"game.exe";
    DWORD pid = FindPid(exe);
    if (!pid) { wprintf(L"[!] 进程未找到: %s\n", exe); return 1; }
    HANDLE h = OpenProcess(PROCESS_VM_READ | PROCESS_QUERY_INFORMATION, FALSE, pid);
    if (!h) { wprintf(L"[!] OpenProcess 失败 GetLastError=%lu（可能被句柄保护剥权限）\n", GetLastError()); return 2; }
    ULONG_PTR base = FindModBase(pid, exe);
    wprintf(L"[+] PID=%lu  Base=0x%llX\n", pid, (unsigned long long)base);

    // 备份前 0x1000 字节，作为回滚基线
    BYTE buf[0x1000]{}; SIZE_T rd = 0;
    if (ReadProcessMemory(h, (LPCVOID)base, buf, sizeof(buf), &rd)) {
        FILE* f = nullptr; _wfopen_s(&f, L"game_base_backup.bin", L"wb");
        if (f) { fwrite(buf, 1, rd, f); fclose(f); wprintf(L"[+] 基线已备份 game_base_backup.bin (%zu 字节)\n", rd); }
    } else wprintf(L"[!] RPM 失败 GetLastError=%lu\n", GetLastError());
    CloseHandle(h); return 0;
}
```

